export const INTERACTION_STORAGE_KEY="incredible-india-interactions";export const MAX_EVENTS=300;export const EVENT_TYPES=Object.freeze({VIEW:"view",BOOKMARK:"bookmark",UNBOOKMARK:"unbookmark",SEARCH:"search",RATING:"rating",TRIP_PLANNED:"trip_planned"});function memoryStorage(){const t=new Map;return{getItem:e=>t.has(e)?t.get(e):null,setItem:(e,r)=>t.set(e,r)}}function safeLocalStorage(){try{return"undefined"==typeof localStorage?null:localStorage}catch{return null}}export class InteractionTracker{constructor(t={}){this.storage=t.storage||safeLocalStorage()||memoryStorage()}_read(){try{const t=this.storage.getItem(INTERACTION_STORAGE_KEY),e=t?JSON.parse(t):[];return Array.isArray(e)?e:[]}catch{return[]}}_write(t){const e=t.slice(-300);return this.storage.setItem(INTERACTION_STORAGE_KEY,JSON.stringify(e)),e}track(t){if(!t||!Object.values(EVENT_TYPES).includes(t.type))throw new Error(`InteractionTracker.track: unknown event type "${t&&t.type}"`);const e={timestamp:Date.now(),...t},r=this._read();return r.push(e),this._write(r)}getEvents(){return this._read()}clearEvents(){return this._write([])}}export default InteractionTracker;